additionalExercises.referenceSolution:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char word[128];
    char op = ';';
    int status = 0;
    while (scanf("%127s", word) == 1) {
        if (strcmp(word, "&&") == 0 || strcmp(word, "||") == 0 || strcmp(word, ";") == 0) {
            op = word[0];
            continue;
        }
        char *colon = strrchr(word, ':');
        int code = 0;
        if (colon != NULL) {
            *colon = '\0';
            code = atoi(colon + 1);
        }
        int run = op == ';' || (op == '&' && status == 0) || (op == '|' && status != 0);
        if (run) {
            status = code;
            printf("%s -> %d\n", word, code);
        } else {
            printf("%s -> пропущена\n", word);
        }
    }
    printf("итог: %d\n", status);
    return 0;
}

